WITH t AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin) SELECT $1,'M9-TXSRC', min(milestone_id), 9992, 'подсадка самотеста', 'S', 'closed', 'dev', 'declared' FROM project_plan_tasks WHERE project_id=$1 RETURNING id) INSERT INTO code_fact(project_id, kind, name, detail) SELECT $1,'contract-schema','проба_xsrc.колонка','помечено x-source: task:' || t.id || ' — проба' FROM t
